<x-admin-layout :title="ucfirst($resource)"><div class="checkout-grid"><section><h2>{{ $record->exists?'Edit entry':'New entry' }}</h2><form method="post" enctype="multipart/form-data" action="/admin/content/{{ $resource }}{{ $record->exists?'/'.$record->id:'' }}">@csrf @php($fields=match($resource){'categories'=>['name','slug','description','seo_title','meta_description'],'pages'=>['title','slug','content','seo_title','meta_description'],'blog'=>['title','slug','author','excerpt','content','published_at','seo_title','meta_description'],'coupons'=>['code','percent','minimum','usage_limit','expires_at']})@foreach($fields as $field)<label>{{ ucfirst(str_replace('_',' ',$field)) }}@if(in_array($field,['description','content','excerpt','meta_description']))<textarea name="{{ $field }}" rows="{{ $field==='content'?10:3 }}">{{ old($field,$record->$field) }}</textarea>@else<input name="{{ $field }}" value="{{ old($field,$record->$field) }}" @if(in_array($field,['percent','minimum','usage_limit']))type="number" min="0" @endif @if(in_array($field,['published_at','expires_at']))placeholder="YYYY-MM-DD HH:MM:SS"@endif>@endif</label> @endforeach @if(in_array($resource,['categories','blog']))@if($record->image)<div class="media-preview"><img src="{{ Storage::url($record->image) }}" alt="Current content image" width="220"><label class="check"><input type="checkbox" name="remove_image" value="1">Remove current image</label></div>@endif<label>Image (JPEG, PNG, WebP; 4 MB max)<input type="file" name="image_upload" accept="image/jpeg,image/png,image/webp"></label>@endif @if(in_array($resource,['categories','pages']))<label class="check"><input type="checkbox" name="published" value="1" @checked(old('published',$record->published))>Published</label>@elseif($resource==='coupons')<label class="check"><input type="checkbox" name="active" value="1" @checked(old('active',$record->active))>Active</label><p class="small">Minimum is in paisa. Usage is transactionally capped.</p>@endif<p class="small">Content is displayed as safe plain text with line breaks. Policies must be reviewed and approved by the business owner before launch.</p><button class="button">Save entry ↗</button></form></section><aside><div class="section-head"><h2>Entries</h2><a href="/admin/content/{{ $resource }}">New +</a></div>@foreach($records as $entry)<a class="content-entry" href="/admin/content/{{ $resource }}/{{ $entry->id }}">{{ $entry->name??$entry->title??$entry->code }} ↗</a>@endforeach{{ $records->links() }}</aside></div></x-admin-layout>